def count_solutions(x):
    """
    Counts the number of positive integers y such that 1/x + 1/y is a unit fraction.
    This is equivalent to counting positive divisors d of x^2 such that d <= x - 1.
    """
    if x == 1:
        return 0

    x_squared = x * x
    limit = x - 1

    divisors = []
    for i in range(1, int(x_squared**0.5) + 1):
        if x_squared % i == 0:
            d1 = i
            d2 = x_squared // i

            if d1 <= limit:
                divisors.append(d1)

            # Avoid double counting if x_squared is a perfect square (d1 == d2)
            if d1 != d2 and d2 <= limit:
                divisors.append(d2)

    return len(divisors)

