def count_divisors_x2(x):
    d = 2
    count = 1
    temp_x = x
    while d * d <= temp_x:
        if temp_x % d == 0:
            a = 0
            while temp_x % d == 0:
                a += 1
                temp_x //= d
            count *= (2 * a + 1)
        d += 1
    if temp_x > 1:
        count *= (2 * 1 + 1)
    return count

